import{_ as o,o as e,c as t,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/PDF-PostScript-SVG-and-PNG-Output-Options.md","filePath":"manual-zh/PDF-PostScript-SVG-and-PNG-Output-Options.md","lastUpdated":1785684581000}'),n={name:"manual-zh/PDF-PostScript-SVG-and-PNG-Output-Options.md"};function d(r,p,c,a,P,s){return e(),t("div",null,[...p[0]||(p[0]=[i('<h3 id="_3-2-pdf、postscript、svg-和-png-输出选项" tabindex="-1">3.2 PDF、PostScript、SVG 和 PNG 输出选项 <a class="header-anchor" href="#_3-2-pdf、postscript、svg-和-png-输出选项" aria-label="Permalink to &quot;3.2 PDF、PostScript、SVG 和 PNG 输出选项&quot;">​</a></h3><p>要以 PDF、PostScript、SVG 或 PNG 格式生成输出，请在 PSPP 命令行上指定 -o file，并可选择性地在其后加上下表所示的任何选项以自定义输出格式。</p><p>PDF、PostScript 和 SVG 使用真实单位：下面列出的每个尺寸可以带有后缀 ‘mm’ 表示毫米、‘in’ 表示英寸，或 ‘pt’ 表示点。缺少后缀时，小于 50 的数字假定为英寸，大于 50 的数字假定为毫米。</p><p>PNG 文件基于像素，因此 PNG 输出中的尺寸最终必须以像素度量。对于这些文件的输出，PSPP 以每英寸 72 像素的比例将指定的尺寸转换为像素。仅对于 PNG 输出，字体默认以更大的每英寸 96 像素渲染。</p><p>一个 SVG 或 PNG 文件只能容纳一页。当 PSPP 向 SVG 或 PNG 输出超过一页时，它会创建多个文件。它将第二页输出到带有 <code>-2</code> 后缀的文件，第三页带有 <code>-3</code> 后缀，依此类推。</p><p>-O format={pdf|ps|svg|png}</p><p>指定输出格式。仅当 -o 上给出的文件名不以 .pdf、.ps、.svg 或 .png 结尾时才需要。</p><p>-O paper-size=paper-size</p><p>纸张尺寸，以名称（<em>例如</em> <code>a4</code>、<code>letter</code>）或度量（<em>例如</em> <code>210x297</code>、<code>8.5x11in</code>）表示。</p><p>默认纸张尺寸取自 <code>PAPERSIZE</code> 环境变量，或 <code>PAPERCONF</code> 环境变量所指示的文件（如果设置了其中任一变量）。如果没有，且你的系统支持 <code>LC_PAPER</code> 区域设置类别，则默认纸张尺寸取自区域设置。否则，如果 /etc/papersize 存在，则从其中读取默认纸张尺寸。作为最后的手段，假定为 A4 纸。</p><p>-O foreground-color=color</p><p>将颜色设为线条和文本的默认颜色。使用 CSS 颜色格式（如 <code>#rrggbb</code>）或名称（如 <code>black</code>）作为 color。</p><p>-O orientation=orientation</p><p><code>portrait</code>（纵向）或 <code>landscape</code>（横向）。默认：<code>portrait</code>。</p><p>-O left-margin=dimension -O right-margin=dimension -O top-margin=dimension -O bottom-margin=dimension</p><p>设置页面四周的页边距。允许的尺寸形式见下文。默认：<code>0.5in</code>。</p><p>-O object-spacing=dimension</p><p>设置对象（如标题或表格）之间的垂直间距。</p><p>-O prop-font=font-name</p><p>设置用于普通文本的默认字体。大多数系统支持类似 CSS 的字体名称，如 “Sans Serif”，但也可能支持范围广泛的特定于系统的字体。</p><p>默认：比例字体 <code>Sans Serif</code>。</p><p>-O font-size=font-size</p><p>设置默认字体的大小，以千分之一磅为单位。默认：10000（10 磅）。</p><p>-O trim=true</p><p>此选项使 PSPP 在添加页边距之前裁剪每页输出周围的空白。这可以使其更易于包含在其他文档中。</p><p>-O outline=boolean</p><p>仅用于 PDF 输出，此选项控制 PSPP 是否在输出文件中包含大纲。PDF 查看器通常将大纲显示为侧边栏，便于在文件中导航。除非同时指定了 -O trim=true，否则默认为 true。（PSPP 用于生成 PDF 输出的 Cairo 图形库有一个 bug，当轮廓和裁剪一起使用时可能导致崩溃。）</p><p>-O font-resolution=dpi</p><p>设置字体渲染的分辨率，以每英寸点数计。对于 PDF、PostScript 和 SVG 输出，默认值为 72 dpi，因此 10 磅字体渲染后的高度为 10 磅。对于 PNG 输出，默认值为 96 dpi，因此 10 磅字体渲染后的高度为 <em>10 / 72 * 96 = 13.3</em> 像素。使用较大的 dpi 放大文本输出，或使用较小的 dpi 缩小文本输出。</p>',29)])])}const l=o(n,[["render",d]]);export{m as __pageData,l as default};
